code.solution:
from fastapi import FastAPI, Query

app = FastAPI()

@app.get("/deployment-choice")
async def deployment_choice(managed: bool = Query()) -> dict[str, object]:
    if managed:
        return {"model": "managed", "platform_handles": ["https", "replication"], "team_handles": ["data", "auth", "secrets"]}
    return {"model": "self-managed", "platform_handles": [], "team_handles": ["https", "restarts", "replication", "data", "auth", "secrets"]}

