from fastapi import FastAPI, Query

app = FastAPI()

def recommended_workers(cpu_count: int, memory_mb: int, per_worker_mb: int) -> int:
    memory_limit = max(1, memory_mb // per_worker_mb)
    return max(1, min(cpu_count, memory_limit))

@app.get("/worker-plan")
async def worker_plan(cpu: int = Query(ge=1), memory_mb: int = Query(ge=1), per_worker_mb: int = Query(gt=0)) -> dict[str, int]:
    return {"workers": recommended_workers(cpu, memory_mb, per_worker_mb)}

from fastapi import FastAPI, Response, status

app = FastAPI()
startup_complete = True
RUNTIME_UID = 65532

@app.get("/healthz")
async def healthz(response: Response) -> dict[str, object]:
    if not startup_complete:
        response.status_code = status.HTTP_503_SERVICE_UNAVAILABLE
    return {"ready": startup_complete, "runtime_uid": RUNTIME_UID}
